example.code:
// 创建帮助类
var options = Options.Create(new SqliteSugarOptions
{
    DatabasePath = "mydata.db"
});
var helper = new SqlSugarDbHelper(options);

// 创建表
helper.CreateTable<User>();

// 插入数据（无需写SQL）
var user = new User { Name = "张三", Age = 25 };
helper.Insert(user);

// 查询数据（Lambda表达式）
var users = helper.GetList<User>(u => u.Age > 18);

// 分页查询
var pagedResult = await helper.GetPageListAsync<User>(
    u => u.IsActive,
    pageIndex: 1,
    pageSize: 10,
    orderByExpression: u => u.CreateTime,
    isAsc: false);

services.AddSqlServerSugar(options =>
{
    options.Server = "localhost";
    options.Database = "MyDatabase";
    options.UserId = "sa";
    options.Password = "YourPassword";
    options.EnableSqlLog = true;
});

services.AddMySqlSugar(options =>
{
    options.Server = "localhost";
    options.Port = 3306;
    options.Database = "mydb";
    options.UserId = "root";
    options.Password = "password";
    options.EnableSqlLog = true;
});

services.AddSqlSugarFactory();

// 使用工厂
var factory = serviceProvider.GetRequiredService<ISqlSugarDbHelperFactory>();
var sqliteHelper = factory.CreateSqlite("mydata.db");

services.AddMySql(options =>
{
    options.Server = "localhost";
    options.Port = 3306;
    options.Database = "mydb";
    options.UserId = "root";
    options.Password = "password";
});

services.AddDatabaseFactory();

// 使用工厂
var factory = serviceProvider.GetRequiredService<IDbHelperFactory>();
var sqliteHelper = factory.Create(DatabaseType.Sqlite, "Data Source=test.db");

// 创建MySQL帮助类
var options = Options.Create(new MySqlOptions
{
    Server = "localhost",
    Port = 3306,
    Database = "mydb",
    UserId = "root",
    Password = "password"
});

using var helper = new MySqlHelper(options);

// 创建表
await helper.ExecuteNonQueryAsync(@"
    CREATE TABLE IF NOT EXISTS Users (
        Id INT AUTO_INCREMENT PRIMARY KEY,
        Name VARCHAR(100) NOT NULL,
        Email VARCHAR(200) UNIQUE,
        CreatedAt DATETIME DEFAULT CURRENT_TIMESTAMP
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");

// 插入数据
var id = await helper.InsertAndGetIdAsync(
    "INSERT INTO Users (Name, Email) VALUES (@Name, @Email)",
    new { Name = "张三", Email = "zhang@example.com" });

// 创建 MySQL 帮助类
var options = Options.Create(new MySqlSugarOptions
{
    Server = "localhost",
    Port = 3306,
    Database = "mydb",
    UserId = "root",
    Password = "password"
});

using var db = new MySqlSugarHelper(options);

// 自动创建表
db.CreateTable<User>();

// 批量插入（高性能）
var users = new List<User> { ... };
db.BulkInsert(users);

// 插入或更新（ON DUPLICATE KEY UPDATE）
db.InsertOrUpdate(user);

// 创建SQLite帮助类
var options = Options.Create(new SqliteOptions
{
    DatabasePath = "mydata.db",
    JournalMode = SqliteJournalMode.Wal
});

using var helper = new SqliteHelper(options);

// 创建表
await helper.ExecuteNonQueryAsync(@"
    CREATE TABLE IF NOT EXISTS Users (
        Id INTEGER PRIMARY KEY AUTOINCREMENT,
        Name TEXT NOT NULL,
        Email TEXT UNIQUE
    )");

// 插入数据
await helper.ExecuteNonQueryAsync(
    "INSERT INTO Users (Name, Email) VALUES (@Name, @Email)",
    new { Name = "张三", Email = "zhang@example.com" });

// 查询数据
var users = await helper.QueryAsync<User>("SELECT * FROM Users");

// 创建 SQLite 帮助类
var options = Options.Create(new SqliteSugarOptions
{
    DatabasePath = "mydata.db"
});

using var db = new SqliteSugarHelper(options);

// 自动创建表（根据实体类）
db.CreateTable<User>();

// 插入数据（无需写SQL）
var user = new User { Name = "张三", Age = 25 };
db.Insert(user);

// 查询数据（Lambda表达式）
var users = db.GetList<User>(u => u.Age > 18);

// 更新数据
user.Age = 26;
db.Update(user);

// 条件更新（只更新指定字段）
db.Update<User>(
    u => new User { Age = 30 },
    u => u.Name == "张三");

// 删除数据
db.Delete<User>(u => u.Age < 18);

// 创建SQL Server帮助类
var options = Options.Create(new SqlServerOptions
{
    Server = "localhost",
    Database = "MyDatabase",
    UserId = "sa",
    Password = "YourPassword",
    TrustServerCertificate = true
});

using var helper = new SqlServerHelper(options);

// 测试连接
if (await helper.TestConnectionAsync())
{
    Console.WriteLine("连接成功!");
}

// 执行存储过程
var result = await helper.ExecuteStoredProcedureAsync<User>(
    "sp_GetUserById",
    new { UserId = 1 });

// 创建 SQL Server 帮助类
var options = Options.Create(new SqlServerSugarOptions
{
    Server = "localhost",
    Database = "MyDatabase",
    UserId = "sa",
    Password = "YourPassword"
});

using var db = new SqlServerSugarHelper(options);

// 自动创建表
db.CreateTable<User>();

// 批量插入（高性能）
var users = new List<User> { ... };
db.BulkInsert(users);

// 存储过程调用
var result = db.ExecuteStoredProcedure<User>("sp_GetUsers", new { Age = 18 });
